import { z } from 'zod';
import { requireUser } from '@/lib/auth';
import { json, readJson, route, HttpError } from '@/lib/http';
import { audit } from '@/lib/audit';
import { searchForPractitioner } from '@/repos/patients';

const Body = z.object({ q: z.string().trim().min(2).max(100) });

/**
 * Patient name search. POST with the term in the body: a GET query string would be
 * written to the Apache access log.
 */
export const POST = route(async (req) => {
  const user = await requireUser(req);
  if (user.role !== 'practitioner' || !user.practitionerId) throw new HttpError(403, 'forbidden');
  const { q } = Body.parse(await readJson(req));
  const rows = await searchForPractitioner(user.orgId, user.practitionerId, q, 20);
  await audit(user, 'patient.search', 'practitioner', user.practitionerId);
  return json({
    results: rows.map((p) => ({
      id: p.id,
      firstName: p.first_name,
      lastName: p.last_name,
      dateOfBirth: p.date_of_birth,
    })),
  });
});
